/* qrcode.min.js — A reliable QR Code generator (pure JS)
 * Adapted from qrcode-generator by Kazuhiko Arase (MIT-equivalent)
 * API:
 *   QRCode.toCanvas(canvasEl, text, { width: 200, margin: 4, color:{ dark:'#000', light:'#fff' } })
 */
(function (root) {
  'use strict';

  // ---------- GFM (GF(256)) math ----------
  var EXP = new Array(256), LOG = new Array(256);
  (function () {
    var x = 1;
    for (var i = 0; i < 255; i++) {
      EXP[i] = x;
      LOG[x] = i;
      x <<= 1;
      if (x & 0x100) x ^= 0x11D;
    }
    EXP[255] = EXP[0];
  })();
  function gexp(n) { while (n < 0) n += 255; while (n >= 256) n -= 255; return EXP[n]; }
  function glog(n) {
    if (n < 1) throw new Error('glog(' + n + ')');
    return LOG[n];
  }

  // ---------- Polynomial ----------
  function Polynomial(num, shift) {
    if (typeof num.length !== 'number') throw new Error('num.length');
    var offset = 0;
    while (offset < num.length && num[offset] === 0) offset++;
    this.num = new Array(num.length - offset + shift);
    for (var i = 0; i < num.length - offset; i++) this.num[i] = num[i + offset];
  }
  Polynomial.prototype.getAt = function (i) { return this.num[i]; };
  Polynomial.prototype.getLength = function () { return this.num.length; };
  Polynomial.prototype.multiply = function (e) {
    var num = new Array(this.getLength() + e.getLength() - 1);
    for (var i = 0; i < this.getLength(); i++)
      for (var j = 0; j < e.getLength(); j++)
        num[i + j] ^= gexp(glog(this.getAt(i)) + glog(e.getAt(j)));
    return new Polynomial(num, 0);
  };
  Polynomial.prototype.mod = function (e) {
    if (this.getLength() - e.getLength() < 0) return this;
    var ratio = glog(this.getAt(0)) - glog(e.getAt(0));
    var num = new Array(this.getLength());
    for (var i = 0; i < e.getLength(); i++)
      num[i] = this.getAt(i) ^ gexp(glog(e.getAt(i)) + ratio);
    for (var i = e.getLength(); i < this.getLength(); i++)
      num[i] = this.getAt(i);
    return new Polynomial(num, 0).mod(e);
  };

  // ---------- BitBuffer ----------
  function BitBuffer() { this.buffer = []; this.length = 0; }
  BitBuffer.prototype.getAt = function (i) {
    return ((this.buffer[Math.floor(i / 8)] >>> (7 - i % 8)) & 1) === 1;
  };
  BitBuffer.prototype.put = function (num, length) {
    for (var i = 0; i < length; i++) this.putBit(((num >>> (length - i - 1)) & 1) === 1);
  };
  BitBuffer.prototype.getLengthInBits = function () { return this.length; };
  BitBuffer.prototype.putBit = function (bit) {
    var bi = Math.floor(this.length / 8);
    if (this.buffer.length <= bi) this.buffer[bi] = 0;
    if (bit) this.buffer[bi] |= (0x80 >>> (this.length % 8));
    this.length++;
  };

  // ---------- 8-bit byte data ----------
  function utf8Bytes(s) {
    var bytes = [], i, c, c2, cp;
    for (i = 0; i < s.length; i++) {
      c = s.charCodeAt(i);
      if (c < 0x80) bytes.push(c);
      else if (c < 0x800) {
        bytes.push(0xc0 | (c >> 6));
        bytes.push(0x80 | (c & 0x3f));
      } else if (c < 0xd800 || c >= 0xe000) {
        bytes.push(0xe0 | (c >> 12));
        bytes.push(0x80 | ((c >> 6) & 0x3f));
        bytes.push(0x80 | (c & 0x3f));
      } else {
        i++;
        c2 = s.charCodeAt(i);
        cp = 0x10000 + (((c & 0x3ff) << 10) | (c2 & 0x3ff));
        bytes.push(0xf0 | (cp >> 18));
        bytes.push(0x80 | ((cp >> 12) & 0x3f));
        bytes.push(0x80 | ((cp >> 6) & 0x3f));
        bytes.push(0x80 | (cp & 0x3f));
      }
    }
    return bytes;
  }

  // ---------- RS Block ----------
  function RSBlock(totalCount, dataCount) {
    this.totalCount = totalCount;
    this.dataCount = dataCount;
  }
  RSBlock.getRsBlockTable = function (typeNumber) {
    switch (typeNumber) {
      case 1:  return [new RSBlock(26, 19)];
      case 2:  return [new RSBlock(44, 34)];
      case 3:  return [new RSBlock(70, 55)];
      case 4:  return [new RSBlock(100, 80)];
      case 5:  return [new RSBlock(134, 108)];
      case 6:  return [new RSBlock(172, 136)];
      case 7:  return [new RSBlock(196, 156)];
      case 8:  return [new RSBlock(242, 194)];
      case 9:  return [new RSBlock(292, 232)];
      case 10: return [new RSBlock(346, 274)];
    }
    return [];
  };

  // ---------- Pattern positions ----------
  function getPatternPosition(t) {
    return [
      [],
      [6, 18],
      [6, 22],
      [6, 26],
      [6, 30],
      [6, 34],
      [6, 22, 38],
      [6, 24, 42],
      [6, 26, 46],
      [6, 28, 50]
    ][t] || [];
  }
  function getMaskFunction(pattern) {
    switch (pattern) {
      case 0: return function (i, j) { return (i + j) % 2 === 0; };
      case 1: return function (i, j) { return i % 2 === 0; };
      case 2: return function (i, j) { return j % 3 === 0; };
      case 3: return function (i, j) { return (i + j) % 3 === 0; };
      case 4: return function (i, j) { return (Math.floor(i / 2) + Math.floor(j / 3)) % 2 === 0; };
      case 5: return function (i, j) { return (i * j) % 2 + (i * j) % 3 === 0; };
      case 6: return function (i, j) { return ((i * j) % 2 + (i * j) % 3) % 2 === 0; };
      case 7: return function (i, j) { return ((i + j) % 2 + (i * j) % 3) % 2 === 0; };
    }
    throw new Error('bad maskPattern');
  }
  function getBCHDigit(data) {
    var d = 0;
    while (data !== 0) { d++; data >>>= 1; }
    return d;
  }
  function getBCHTypeInfo(data) {
    var d = data << 10, G = 0x537;
    while (getBCHDigit(d) - getBCHDigit(G) >= 0) d ^= G << (getBCHDigit(d) - getBCHDigit(G));
    return ((data << 10) | d) ^ 0x5412;
  }
  function getBCHTypeNumber(data) {
    var d = data << 12, G = 0x1F25;
    while (getBCHDigit(d) - getBCHDigit(G) >= 0) d ^= G << (getBCHDigit(d) - getBCHDigit(G));
    return (data << 12) | d;
  }
  function getLengthInBits(mode, type) {
    if (1 <= type && type < 10) {
      if (mode === 1) return 8;
      if (mode === 2) return 10;
      if (mode === 4) return 8;
      if (mode === 8) return 10;
    } else if (type < 27) {
      if (mode === 1) return 16;
      if (mode === 2) return 12;
      if (mode === 4) return 16;
      if (mode === 8) return 12;
    } else {
      if (mode === 1) return 16;
      if (mode === 2) return 14;
      if (mode === 4) return 16;
      if (mode === 8) return 14;
    }
    throw new Error('mode/type combo');
  }

  // ---------- Build error-corrected bytes ----------
  function createBytes(buffer, rsBlocks) {
    var offset = 0, maxDcCount = 0, maxEcCount = 0;
    var dcdata = new Array(rsBlocks.length);
    var ecdata = new Array(rsBlocks.length);
    for (var r = 0; r < rsBlocks.length; r++) {
      var dcCount = rsBlocks[r].dataCount;
      var ecCount = rsBlocks[r].totalCount - dcCount;
      maxDcCount = Math.max(maxDcCount, dcCount);
      maxEcCount = Math.max(maxEcCount, ecCount);
      dcdata[r] = new Array(dcCount);
      for (var i = 0; i < dcdata[r].length; i++) dcdata[r][i] = 0xff & buffer.buffer[i + offset];
      offset += dcCount;
      var rawPoly = new Polynomial(dcdata[r], 0);
      var gen = new Polynomial([1], 0);
      for (var i2 = 0; i2 < ecCount; i2++) {
        gen = gen.multiply(new Polynomial([1, gexp(i2)], 0));
      }
      var modPoly = rawPoly.mod(gen);
      ecdata[r] = new Array(ecCount);
      for (var i3 = 0; i3 < ecdata[r].length; i3++) {
        var modIndex = i3 + modPoly.getLength() - ecCount;
        ecdata[r][i3] = modIndex >= 0 ? modPoly.getAt(modIndex) : 0;
      }
    }
    var totalCodeCount = 0;
    for (var i4 = 0; i4 < rsBlocks.length; i4++) totalCodeCount += rsBlocks[i4].totalCount;
    var data = new Array(totalCodeCount);
    var index = 0;
    for (var i5 = 0; i5 < maxDcCount; i5++)
      for (var r2 = 0; r2 < rsBlocks.length; r2++) if (i5 < dcdata[r2].length) data[index++] = dcdata[r2][i5];
    for (var i6 = 0; i6 < maxEcCount; i6++)
      for (var r3 = 0; r3 < rsBlocks.length; r3++) if (i6 < ecdata[r3].length) data[index++] = ecdata[r3][i6];
    return data;
  }

  function createData(typeNumber, ecLevel, dataBytes) {
    var rsBlocks = RSBlock.getRsBlockTable(typeNumber);
    var buffer = new BitBuffer();
    for (var i = 0; i < dataBytes.length; i++) {
      var data = dataBytes[i];
      buffer.put(4, 4); // byte mode
      buffer.put(data.length, getLengthInBits(4, typeNumber));
      for (var j = 0; j < data.length; j++) buffer.put(data[j], 8);
    }
    var totalDataCount = 0;
    for (var k = 0; k < rsBlocks.length; k++) totalDataCount += rsBlocks[k].dataCount;
    if (buffer.getLengthInBits() > totalDataCount * 8) throw new Error('code length overflow');
    if (buffer.getLengthInBits() + 4 <= totalDataCount * 8) buffer.put(0, 4);
    while (buffer.getLengthInBits() % 8 !== 0) buffer.putBit(false);
    while (true) {
      if (buffer.getLengthInBits() >= totalDataCount * 8) break;
      buffer.put(0xEC, 8);
      if (buffer.getLengthInBits() >= totalDataCount * 8) break;
      buffer.put(0x11, 8);
    }
    return createBytes(buffer, rsBlocks);
  }

  // ---------- QR Code model ----------
  function QRCodeModel(typeNumber) {
    this.typeNumber = typeNumber;
    this.modules = null;
    this.moduleCount = 0;
    this.dataCache = null;
    this.dataList = [];
  }
  QRCodeModel.prototype.addData = function (bytes) {
    this.dataList.push(bytes);
    this.dataCache = null;
  };
  QRCodeModel.prototype.isDark = function (row, col) {
    return !!this.modules[row][col];
  };
  QRCodeModel.prototype.getModuleCount = function () { return this.moduleCount; };

  QRCodeModel.prototype.make = function () {
    this.makeImpl(false, this.getBestMaskPattern());
  };

  QRCodeModel.prototype.makeImpl = function (test, maskPattern) {
    this.moduleCount = this.typeNumber * 4 + 17;
    this.modules = [];
    for (var row = 0; row < this.moduleCount; row++) {
      this.modules.push(new Array(this.moduleCount));
      for (var col = 0; col < this.moduleCount; col++) this.modules[row][col] = null;
    }
    this.setupPositionProbePattern(0, 0);
    this.setupPositionProbePattern(this.moduleCount - 7, 0);
    this.setupPositionProbePattern(0, this.moduleCount - 7);
    this.setupPositionAdjustPattern();
    this.setupTimingPattern();
    this.setupTypeInfo(test, maskPattern);
    if (this.typeNumber >= 7) this.setupTypeNumber(test);
    if (this.dataCache === null) {
      this.dataCache = createData(this.typeNumber, 2, this.dataList);
    }
    this.mapData(this.dataCache, maskPattern);
  };

  QRCodeModel.prototype.setupPositionProbePattern = function (row, col) {
    for (var r = -1; r <= 7; r++) {
      if (row + r <= -1 || this.moduleCount <= row + r) continue;
      for (var c = -1; c <= 7; c++) {
        if (col + c <= -1 || this.moduleCount <= col + c) continue;
        this.modules[row + r][col + c] =
          (0 <= r && r <= 6 && (c === 0 || c === 6)) ||
          (0 <= c && c <= 6 && (r === 0 || r === 6)) ||
          (2 <= r && r <= 4 && 2 <= c && c <= 4);
      }
    }
  };

  QRCodeModel.prototype.getBestMaskPattern = function () {
    var minLostPoint = 0, pattern = 0;
    for (var i = 0; i < 8; i++) {
      this.makeImpl(true, i);
      var lostPoint = QRCodeModel.getLostPoint(this);
      if (i === 0 || minLostPoint > lostPoint) { minLostPoint = lostPoint; pattern = i; }
    }
    return pattern;
  };

  QRCodeModel.prototype.setupPositionAdjustPattern = function () {
    var pos = getPatternPosition(this.typeNumber);
    for (var i = 0; i < pos.length; i++) {
      for (var j = 0; j < pos.length; j++) {
        var row = pos[i], col = pos[j];
        if (this.modules[row][col] !== null) continue;
        for (var r = -2; r <= 2; r++) {
          for (var c = -2; c <= 2; c++) {
            this.modules[row + r][col + c] = (r === -2 || r === 2 || c === -2 || c === 2 || (r === 0 && c === 0));
          }
        }
      }
    }
  };

  QRCodeModel.prototype.setupTimingPattern = function () {
    for (var r = 8; r < this.moduleCount - 8; r++) {
      if (this.modules[r][6] !== null) continue;
      this.modules[r][6] = (r % 2 === 0);
    }
    for (var c = 8; c < this.moduleCount - 8; c++) {
      if (this.modules[6][c] !== null) continue;
      this.modules[6][c] = (c % 2 === 0);
    }
  };

  QRCodeModel.prototype.setupTypeInfo = function (test, maskPattern) {
    var data = (2 << 3) | maskPattern; // EC level M = 2
    var bits = getBCHTypeInfo(data);
    for (var i = 0; i < 15; i++) {
      var mod = (!test && ((bits >> i) & 1) === 1);
      this.modules[(i < 6 ? i : (i < 8 ? i + 1 : this.moduleCount - 15 + i))][8] = mod;
    }
    this.modules[this.moduleCount - 8][8] = (!test);
  };

  QRCodeModel.prototype.setupTypeNumber = function (test) {
    var bits = getBCHTypeNumber(this.typeNumber);
    for (var i = 0; i < 18; i++) {
      var mod = (!test && ((bits >> i) & 1) === 1);
      this.modules[Math.floor(i / 3)][i % 3 + this.moduleCount - 8 - 3] = mod;
    }
    for (var ii = 0; ii < 18; ii++) {
      var mod2 = (!test && ((bits >> ii) & 1) === 1);
      this.modules[ii % 3 + this.moduleCount - 8 - 3][Math.floor(ii / 3)] = mod2;
    }
  };

  QRCodeModel.prototype.mapData = function (data, maskPattern) {
    var inc = -1, row = this.moduleCount - 1, bitIndex = 7, byteIndex = 0;
    var maskFunc = getMaskFunction(maskPattern);
    for (var col = this.moduleCount - 1; col > 0; col -= 2) {
      if (col === 6) col--;
      while (true) {
        for (var c = 0; c < 2; c++) {
          if (this.modules[row][col - c] === null) {
            var dark = false;
            if (byteIndex < data.length) dark = (((data[byteIndex] >>> bitIndex) & 1) === 1);
            if (maskFunc(row, col - c)) dark = !dark;
            this.modules[row][col - c] = dark;
            bitIndex--;
            if (bitIndex === -1) { byteIndex++; bitIndex = 7; }
          }
        }
        row += inc;
        if (row < 0 || this.moduleCount <= row) { row -= inc; inc = -inc; break; }
      }
    }
  };

  QRCodeModel.getLostPoint = function (qrcode) {
    var moduleCount = qrcode.getModuleCount();
    var lostPoint = 0;
    // rule 1
    for (var row = 0; row < moduleCount; row++) {
      for (var col = 0; col < moduleCount; col++) {
        var sameCount = 0;
        var dark = qrcode.isDark(row, col);
        for (var r = -1; r <= 1; r++) {
          if (row + r < 0 || moduleCount <= row + r) continue;
          for (var c = -1; c <= 1; c++) {
            if (col + c < 0 || moduleCount <= col + c) continue;
            if (r === 0 && c === 0) continue;
            if (dark === qrcode.isDark(row + r, col + c)) sameCount++;
          }
        }
        if (sameCount > 5) lostPoint += 3 + sameCount - 5;
      }
    }
    // rule 2
    for (var row2 = 0; row2 < moduleCount - 1; row2++) {
      for (var col2 = 0; col2 < moduleCount - 1; col2++) {
        var count = 0;
        if (qrcode.isDark(row2, col2)) count++;
        if (qrcode.isDark(row2 + 1, col2)) count++;
        if (qrcode.isDark(row2, col2 + 1)) count++;
        if (qrcode.isDark(row2 + 1, col2 + 1)) count++;
        if (count === 0 || count === 4) lostPoint += 3;
      }
    }
    // rule 3
    for (var row3 = 0; row3 < moduleCount; row3++) {
      for (var col3 = 0; col3 < moduleCount - 6; col3++) {
        if (qrcode.isDark(row3, col3)
            && !qrcode.isDark(row3, col3 + 1)
            && qrcode.isDark(row3, col3 + 2)
            && qrcode.isDark(row3, col3 + 3)
            && qrcode.isDark(row3, col3 + 4)
            && !qrcode.isDark(row3, col3 + 5)
            && qrcode.isDark(row3, col3 + 6)) lostPoint += 40;
      }
    }
    for (var col4 = 0; col4 < moduleCount; col4++) {
      for (var row4 = 0; row4 < moduleCount - 6; row4++) {
        if (qrcode.isDark(row4, col4)
            && !qrcode.isDark(row4 + 1, col4)
            && qrcode.isDark(row4 + 2, col4)
            && qrcode.isDark(row4 + 3, col4)
            && qrcode.isDark(row4 + 4, col4)
            && !qrcode.isDark(row4 + 5, col4)
            && qrcode.isDark(row4 + 6, col4)) lostPoint += 40;
      }
    }
    // rule 4
    var darkCount = 0;
    for (var col5 = 0; col5 < moduleCount; col5++)
      for (var row5 = 0; row5 < moduleCount; row5++)
        if (qrcode.isDark(row5, col5)) darkCount++;
    var ratio = Math.abs(100 * darkCount / moduleCount / moduleCount - 50) / 5;
    lostPoint += ratio * 10;
    return lostPoint;
  };

  // ---------- Public ----------
  function estimateTypeNumber(bytes) {
    // For EC level M, the data-code capacity (in bytes) per typeNumber is roughly:
    var capacity = [0, 14, 26, 42, 62, 84, 106, 122, 152, 180, 213];
    for (var t = 1; t < capacity.length; t++) {
      if (bytes.length <= capacity[t]) return t;
    }
    return 10;
  }

  function make(text) {
    var bytes = utf8Bytes(text);
    var typeNumber = estimateTypeNumber(bytes);
    var qr = new QRCodeModel(typeNumber);
    qr.addData(bytes);
    qr.make();
    return qr;
  }

  function drawToCanvas(canvas, text, opts) {
    opts = opts || {};
    var margin = (opts.margin == null) ? 4 : opts.margin;
    var dark  = (opts.color && opts.color.dark)  || '#000';
    var light = (opts.color && opts.color.light) || '#fff';
    var qr = make(text);
    var count = qr.getModuleCount();
    var px = Math.max(1, Math.floor((opts.width || 200) / (count + margin * 2)));
    var size = px * (count + margin * 2);
    canvas.width  = size;
    canvas.height = size;
    var ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('canvas.getContext() failed');
    ctx.fillStyle = light;
    ctx.fillRect(0, 0, size, size);
    ctx.fillStyle = dark;
    for (var r = 0; r < count; r++) {
      for (var c = 0; c < count; c++) {
        if (qr.isDark(r, c)) ctx.fillRect((c + margin) * px, (r + margin) * px, px, px);
      }
    }
    return canvas;
  }

  root.QRCode = {
    toCanvas: function (el, text, opts) { return drawToCanvas(el, text, opts); },
    toDataURL: function (text, opts) {
      var c = document.createElement('canvas');
      drawToCanvas(c, text, opts);
      return c.toDataURL('image/png');
    }
  };
})(typeof window !== 'undefined' ? window : (typeof globalThis !== 'undefined' ? globalThis : this));
